import { test, expect } from '@playwright/test';

test.describe('Internet Connection Drop', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://your-application-url.com');
  });

  test('should display friendly message when internet connection drops', async ({ page }) => {
    // Simulate internet connection drop
    await page.evaluate(() => {
      window.dispatchEvent(new Event('offline'));
    });

    // Check for the friendly message
    const message = await page.getByText('It seems you are offline. Please check your internet connection.');
    await expect(message).toBeVisible();
  });

  test('should not display friendly message when internet is connected', async ({ page }) => {
    // Simulate internet connection restored
    await page.evaluate(() => {
      window.dispatchEvent(new Event('online'));
    });

    // Check that the friendly message is not visible
    const message = await page.getByText('It seems you are offline. Please check your internet connection.');
    await expect(message).not.toBeVisible();
  });
});
